&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types de moine&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_de_moine_0&quot; href=&quot;#Les_arch&#233;types_de_moine_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html&quot; title=&quot;Le moine&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Adepte-Des-Armes-(Moine).html&quot; title=&quot;Adepte des armes&quot;&gt;Adepte des armes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Adepte-Du-Feu-Serpent-(Moine).html&quot; title=&quot;Adepte du feu-serpent&quot;&gt;Adepte du feu-serpent&lt;/a&gt; (&lt;i&gt;OO&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Archer-Zen-(Moine).html&quot; title=&quot;Archer zen&quot;&gt;Archer zen&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Artiste-Martial-(Moine).html&quot; title=&quot;Artiste martial&quot;&gt;Artiste martial&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aspic-Noir-(Moine).html&quot; title=&quot;Aspic noir&quot;&gt;Aspic noir&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Champion-Des-Poids-Plume-(Moine).html&quot; title=&quot;Champion des poids plume&quot;&gt;Champion des poids plume&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Halfelin.html&quot; title=&quot;Les halfelins&quot;&gt;Halfelin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chat-Sauvage-(Moine).html&quot; title=&quot;Chat sauvage&quot;&gt;Chat sauvage&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Disciple-Gris-(Moine).html&quot; title=&quot;Disciple gris&quot;&gt;Disciple gris&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Duergar-(Race).html&quot; title=&quot;Les duergars&quot;&gt;Duergar&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;l&#232;ve-De-La-Pierre-(Moine).html&quot; title=&quot;&#201;l&#232;ve de la pierre&quot;&gt;&#201;l&#232;ve de la pierre&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Or&#233;ade-(Race).html&quot; title=&quot;Les or&#233;ades&quot;&gt;Or&#233;ade&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gardien-Agile-(Moine).html&quot; title=&quot;Gardien agile&quot;&gt;Gardien agile&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Homme-F&#233;lin-(Race).html&quot; title=&quot;Les hommes-f&#233;lins&quot;&gt;Homme-f&#233;lin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-&#201;coles-(Moine).html&quot; title=&quot;Ma&#238;tre des &#233;coles&quot;&gt;Ma&#238;tre des &#233;coles&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Katas-(Moine).html&quot; title=&quot;Ma&#238;tre des katas&quot;&gt;Ma&#238;tre des katas&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Manoeuvres-(Moine).html&quot; title=&quot;Ma&#238;tre des manoeuvres&quot;&gt;Ma&#238;tre des manœuvres&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Ivre-(Moine).html&quot; title=&quot;Ma&#238;tre ivre&quot;&gt;Ma&#238;tre ivre&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-&#192;-Peau-De-Fer-(Moine).html&quot; title=&quot;Moine &#224; peau de fer&quot;&gt;Moine &#224; peau de fer&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Hobgobelin-(Race).html&quot; title=&quot;Les hobgobelins&quot;&gt;Hobgobelin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-De-La-Main-Qui-Gu&#233;rit-(Moine).html&quot; title=&quot;Moine de la main qui gu&#233;rit&quot;&gt; Moine de la main qui gu&#233;rit&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-De-La-Main-Vide-(Moine).html&quot; title=&quot;Moine de la main vide&quot;&gt;Moine de la main vide&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-De-La-Montagne-Sacr&#233;e-(Moine).html&quot; title=&quot;Moine de la montagne sacr&#233;e&quot;&gt;Moine de la montagne sacr&#233;e&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Des-Cimes-(Moine).html&quot; title=&quot;Moine des cimes&quot;&gt;Moine des cimes&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Vanara-(Race).html&quot; title=&quot;Les vanaras&quot;&gt;Vanara&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Des-Quatre-Vents-(Moine).html&quot; title=&quot;Moine des quatre vents&quot;&gt;Moine des quatre vents&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Du-Fant&#244;me-Affam&#233;-(Moine).html&quot; title=&quot;Moine du fant&#244;me affam&#233;&quot;&gt; Moine du fant&#244;me affam&#233;&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Du-Lotus-(Moine).html&quot; title=&quot;Moine du lotus&quot;&gt;Moine du lotus&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Fluide-(Moine).html&quot; title=&quot;Moine fluide&quot;&gt;Moine fluide&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Karmique-(Moine).html&quot; title=&quot;Moine karmique&quot;&gt;Moine karmique&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Qinggong-(Moine).html&quot; title=&quot;Moine qinggong&quot;&gt;Moine qinggong&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mystique-Ki-(Moine).html&quot; title=&quot;Mystique ki&quot;&gt;Mystique ki&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sage-Conseiller-(Moine).html&quot; title=&quot;Sage conseiller&quot;&gt;Sage conseiller&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sensei-(Moine).html&quot; title=&quot;Sensei&quot;&gt;Sensei&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sohei-(Moine).html&quot; title=&quot;Sohei&quot;&gt;Sohei&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tetori-(Moine).html&quot; title=&quot;Tetori&quot;&gt;Tetori&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vagabond-(Moine).html&quot; title=&quot;Vagabond&quot;&gt;Vagabond&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;Humain&lt;/a&gt;) (MR)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Le tetori a choisi le style majestueux du lutteur. C’est un guerrier qui dispose d’un arsenal impressionnant de prises gr&#226;ce auxquelles il surprend ses adversaires et les met hors de combat.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Don suppl&#233;mentaire&lt;a class=&quot;headeranchor&quot; id=&quot;Don_suppl&#233;mentaire_0&quot; href=&quot;#Don_suppl&#233;mentaire_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le tetori gagne les dons suppl&#233;mentaires suivants : au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 1 &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-La-Lutte.html&quot; title=&quot;Science de la lutte&quot;&gt;Science de la lutte&lt;/a&gt;, au niveau 2 &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tourdir-Limmobile.html&quot; title=&quot;&#201;tourdir l&amp;#39;immobile&quot;&gt;&#201;tourdir l’immobile&lt;/a&gt;, au niveau 6 &lt;a class=&quot;pagelink&quot; href=&quot;Lutte-Sup&#233;rieure.html&quot; title=&quot;Lutte sup&#233;rieure&quot;&gt;Lutte sup&#233;rieure&lt;/a&gt;, au niveau 10 &lt;a class=&quot;pagelink&quot; href=&quot;Ko-Sur-Limmobile.html&quot; title=&quot;KO sur l&amp;#39;immobile&quot;&gt;KO sur l’immobile&lt;/a&gt;, au niveau 14 &lt;a class=&quot;pagelink&quot; href=&quot;&#201;treinte-&#201;touffante.html&quot; title=&quot;&#201;treinte &#233;touffante&quot;&gt;&#201;treinte &#233;touffante&lt;/a&gt; et au niveau 18 &lt;a class=&quot;pagelink&quot; href=&quot;Briser-Le-Cou.html&quot; title=&quot;Briser le cou&quot;&gt;Briser le cou&lt;/a&gt;. Ces dons remplacent les &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#DONSUPPLEMENTAIRE&quot; title=&quot;Le moine&quot;&gt;dons&lt;/a&gt; suppl&#233;mentaires du moine ordinaire.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Lutteur gracieux (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Lutteur_gracieux_Ext_1&quot; href=&quot;#Lutteur_gracieux_Ext_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un tetori utilise ses niveaux de &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html&quot; title=&quot;Le moine&quot;&gt;moine&lt;/a&gt; &#224; la place de son &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;bonus de base &#224; l’attaque&lt;/a&gt; pour d&#233;terminer son &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Bmo.html&quot; title=&quot;BMO&quot;&gt;BMO&lt;/a&gt; et son &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt;. Au niveau 4, il ne subit plus de malus aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt;, il peut faire des &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;attaque d&amp;#39;opportunit&#233;&quot;&gt;attaques d’opportunit&#233;&lt;/a&gt; quand il est en &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Lutte.html&quot; title=&quot;lutte&quot;&gt;lutte&lt;/a&gt; et il conserve son bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt; &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; quand il immobilise un adversaire ou qu’il est en train de lutter. Au niveau 8, il gagne le pouvoir de monstre &lt;a class=&quot;pagelink&quot; href=&quot;&#201;treinte-(Capacit&#233;).html&quot; title=&quot;&#201;treinte&quot;&gt;&#233;treinte&lt;/a&gt; quand il se bat &#224; mains nues et peut utiliser ce pouvoir contre des cr&#233;atures de sa taille ou plus petites pour 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Moine#Reservedeki.html&quot; title=&quot;ki&quot;&gt;ki&lt;/a&gt;, ou contre des cr&#233;atures plus grandes pour 2 points de ki. Au niveau 15, il gagne &lt;a class=&quot;pagelink&quot; href=&quot;Constriction-(Capacit&#233;).html&quot; title=&quot;constriction&quot;&gt;constriction&lt;/a&gt; et inflige des d&#233;g&#226;ts &#224; mains nues &#224; chaque fois qu’il r&#233;ussit un test de lutte. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#DELUGEDECOUPS&quot; title=&quot;Le moine&quot;&gt;d&#233;luge de coups&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Contre-lutte (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Contre-lutte_Ext_2&quot; href=&quot;#Contre-lutte_Ext_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 4, le lutteur tetori peut faire une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;attaque d&amp;#39;opportunit&#233;&quot;&gt;attaque d’opportunit&#233;&lt;/a&gt; contre une cr&#233;ature qui tente d’entamer une &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Lutte.html&quot; title=&quot;lutte&quot;&gt;lutte&lt;/a&gt; avec lui. Ce pouvoir ne lui permet pas de le faire si la cr&#233;ature dispose de &lt;a class=&quot;pagelink&quot; href=&quot;Lutte-Sup&#233;rieure.html&quot; title=&quot;Lutte sup&#233;rieure&quot;&gt;Lutte sup&#233;rieure&lt;/a&gt;. Au niveau 6, il peut utiliser contre-lutte m&#234;me si son adversaire a un &lt;a class=&quot;pagelink&quot; href=&quot;Modificateurs-De-Combat#Camouflage.html&quot; title=&quot;camouflage&quot;&gt;camouflage&lt;/a&gt; ou un &lt;a class=&quot;pagelink&quot; href=&quot;Modificateurs-De-Combat#Camouflagetotal.html&quot; title=&quot;camouflage total&quot;&gt;camouflage total&lt;/a&gt; et au niveau 8, m&#234;me s’il est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Prisaud&#233;pourvu.html&quot; title=&quot;Pris au d&#233;pourvu&quot;&gt;pris au d&#233;pourvu&lt;/a&gt;. Au niveau 10, le pouvoir fonctionne m&#234;me si son adversaire a une allonge exceptionnelle. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#CHUTERALENTIE&quot; title=&quot;Le moine&quot;&gt;chute ralentie&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Se lib&#233;rer (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Se_lib&#233;rer_Ext_3&quot; href=&quot;#Se_lib&#233;rer_Ext_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 5, le tetori ajoute son niveau de moine aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Manoeuvre-Offensive.html&quot; title=&quot;Manœuvre offensive&quot;&gt;manoeuvre offensive&lt;/a&gt; et d’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;vasion.html&quot; title=&quot;&#201;vasion&quot;&gt;&#201;vasion&lt;/a&gt; pour &#233;chapper &#224; une lutte. Si le tetori rate un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jet de sauvegarde&lt;/a&gt; contre un effet qui l’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Enchev&#234;tr&#233;.html&quot; title=&quot;Enchev&#234;tr&#233;&quot;&gt;enchev&#234;tre&lt;/a&gt;, le &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Paralys&#233;.html&quot; title=&quot;Paralys&#233;&quot;&gt;paralyse&lt;/a&gt;, le ralentit ou le fait &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Chancelant.html&quot; title=&quot;Chancelant&quot;&gt;chanceler&lt;/a&gt; il peut, par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt;, d&#233;penser 1 point de ki pour tenter un nouveau jet. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#SAUTPUISSANT&quot; title=&quot;Le moine&quot;&gt;sauts puissants&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;&#201;treinte in&#233;vitable (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;&#201;treinte_in&#233;vitable_Sur_4&quot; href=&quot;#&#201;treinte_in&#233;vitable_Sur_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 9, le tetori peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Moine#Reservedeki.html&quot; title=&quot;ki&quot;&gt;ki&lt;/a&gt; pour priver son adversaire de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Libert&#233;-De-Mouvement.html&quot; title=&quot;Libert&#233; de mouvement&quot;&gt;libert&#233; de mouvement&lt;/a&gt;&lt;/i&gt; et des bonus magiques aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;vasion.html&quot; title=&quot;&#201;vasion&quot;&gt;&#201;vasion&lt;/a&gt; et aux tests pour &#233;chapper &#224; une lutte. Au niveau 13, ce pouvoir reproduit aussi les effets d’une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ancre-Dimensionnelle.html&quot; title=&quot;Ancre dimensionnelle&quot;&gt;ancre dimensionnelle&lt;/a&gt;&lt;/i&gt;. Au niveau 17, les attaques &#224; mains nues du tetori gagnent la propri&#233;t&#233; &lt;a class=&quot;unknownlink&quot; href=&quot;Spectrale.html&quot; title=&quot;Pathfinder-RPG.spectrale&quot;&gt;spectrales&lt;/a&gt; et il &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Agripp&#233;.html&quot; title=&quot;Agripp&#233;&quot;&gt;agrippe&lt;/a&gt; les cr&#233;atures intangibles qu’il touche (&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;R&#233;flexes&quot;&gt;R&#233;flexes&lt;/a&gt; pour annuler, &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 10 + 1/2 niveau de &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html&quot; title=&quot;Le moine&quot;&gt;moine&lt;/a&gt; + modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sagesse&lt;/a&gt;). L’&#233;treinte in&#233;vitable demande une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt; et dure jusqu’au d&#233;but du prochain tour du tetori. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#ESQUIVEINSTINCTIVE&quot; title=&quot;Le moine&quot;&gt;esquive instinctive&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#ETERNELLEJEUNESSE&quot; title=&quot;Le moine&quot;&gt;&#233;ternelle jeunesse&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#LANGUEDUSOLEILETDELALUNE&quot; title=&quot;Le moine&quot;&gt;langue du soleil et de la lune&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#PASCHASSE&quot; title=&quot;Le moine&quot;&gt;pas chass&#233;&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Blocage de forme (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Blocage_de_forme_Sur_5&quot; href=&quot;#Blocage_de_forme_Sur_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 13, le tetori peut annuler un effet de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tamorphose.html&quot; title=&quot;M&#233;tamorphose&quot;&gt;m&#233;tamorphose&lt;/a&gt;&lt;/i&gt; d’un simple contact, gr&#226;ce &#224; un test de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sagesse&lt;/a&gt; auquel il ajoute son niveau de moine. Il doit battre un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; de 11 + niveau de lanceur de sorts de l’effet (ou &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Desdevie.html&quot; title=&quot;DV&quot;&gt;DV&lt;/a&gt; de la cr&#233;ature pour les effets de m&#233;tamorphose surnaturelle). C’est une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; qui co&#251;te 2 points de ki. Si le tetori est en lutte avec la cr&#233;ature qui tente de lancer l’effet, c’est une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt;. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#AMEDEDIAMANT&quot; title=&quot;Le moine&quot;&gt;&#226;me de diamant&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Corps de fer (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Corps_de_fer_Sur_6&quot; href=&quot;#Corps_de_fer_Sur_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 19, le tetori peut, par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt;, rendre ses tissus incroyablement denses pendant une minute, comme avec un sort de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Corps-De-Fer.html&quot; title=&quot;Corps de fer&quot;&gt;corps de fer&lt;/a&gt;&lt;/i&gt;. Il doit d&#233;penser 3 points de ki. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#DESERTIONDELAME&quot; title=&quot;Le moine&quot;&gt;d&#233;sertion de l’&#226;me&lt;/a&gt;.
